  },
  "license": "MIT",
  "author": "Abdul Rafay Shaikh <me@arafays.com>",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/arafays/opencode-dcp.git"
  },
  "files": [
    "dist",
    "tui.tsx",
    "README.md",
    "LICENSE"
  ],
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
